from pathlib import Path
from zipfile import ZipFile,ZIP_DEFLATED
import hashlib,json,re
from build_pbo import build
r=Path(__file__).resolve().parents[1]
old=json.loads((r/'GRZ-MAP-ROTATION-MANIFEST.json').read_text())
m={'pbo':{},'files':{},'previous_map_hashes':[old['original_map_sha256'],old['sanitized_map_sha256']]+json.loads((r/'packaging/duels/previous-map-hashes.json').read_text())}
with ZipFile(r/'downloads/GRZ-Arena-Menu-Update.zip','w',ZIP_DEFLATED) as z:
 for addon in ['GRZ_Loadout','GRZ_MapRotation','GRZ_DeathScreen','GRZ_CustomHud','GRZ_SFGPermanent','GRZ_AR50Sounds','GRZ_Movement','GRZ_Killfeed','GRZ_AnimatedGhillie','GRZ_AnimatedHexgrid','GRZ_AnimatedHexgridWhite','GRZ_AnimatedHexgridBlackV2','GRZ_XimsCS5']:
  data=build(r/addon)
  assert not re.search(rb'7656119\d{10}', data)
  m['pbo'][addon]={'sha256':hashlib.sha256(data).hexdigest()}
  z.writestr(addon+'.pbo',data)
 data=(r/'packaging/duels/EditorFiles/GRZ_BBC_DM_3.dze').read_bytes()
 m['files']['GRZ_BBC_DM_3.dze']=hashlib.sha256(data).hexdigest()
 z.writestr('GRZ_BBC_DM_3.dze',data)
 data=(r/'packaging/duels/duel-map-update.json').read_bytes()
 m['files']['duel-map-update.json']=hashlib.sha256(data).hexdigest()
 z.writestr('duel-map-update.json',data)
 z.writestr('MANIFEST.json',json.dumps(m,indent=2)+'\n')
 z.write(r/'packaging/arena-update/Install-Update.ps1','Install-Update.ps1')
 z.writestr('INSTALL.txt','Close DayZ and server. Run Install-Update.ps1 -SteamId YOUR_17_DIGIT_ID in PowerShell. The installer preserves existing arena configuration and adds this ID to AdminSteamIds. Requires existing GRZ_MapRotation/config.json, GRZ_Duels/config.json and mission folder (start the server once first if a profile is missing). Also installs the updated GRZ_BBC_DM_3POND map as GRZ_BBC_DM_3.dze, and updates only the Long Range 1v1 duel entry to use the two end platforms with live roadway height. Other duel entries and Elo stay unchanged. Backs up known old map copies outside EditorFiles to avoid duplicates; preserves all other duel entries, the VIP allowlist, prefixes and ratings.\n\nXIMS CS5: new additive reskin, display name XIMS CS5, description Made By Blake, using the four supplied 4K painted textures and the existing CS5 model/materials. VIP gun selector; inherits installed base CS5 ammo and behaviour. VIP menu stays open on Alt-Tab; Esc, CLOSE or the top-right X close it. Preview objects use the native diagnostic-console creation pattern; transparent preview parents and the covering backdrop are removed. VIP live preview: local gun models include fitted scope, compatible suppressor, selected wrap and magazine. Drag models to rotate, scroll to zoom, RESET VIEW restores framing; animated Hexgrids start facing the back. Preview clones never modify the live inventory. VIP animated gear: GUN RESKINS / OTHER equips and saves VIP-only animated clothing, preserving other worn gear and transferring inventory with rollback when it cannot fit. Animated ghillies are in GUN RESKINS under GHILLIE WRAP. Hidden from ordinary clothing/wrap lists. Includes white angel-clip Hexgrid and a second black Hexgrid using the newest clip, with full-back UV placement and cached textures. Animated Hexgrid: GRZ Animated Hexgrid has a solid black base with the supplied anime clip baked into the back-panel UV texture at 8 fps; requires the existing HEXGRID addon. Back placement needs an in-game check. XIMS Ghillie V2: purple/black butterfly wrap swaps every 1 second, with large high-contrast butterfly motifs. Animated cross ghillie: XIMS Ghillie alternates upright and upside-down crosses every 0.75 seconds, preserving the original alpha mask. Available in the VIP ghillie selector. Animated checker ghillie: GRZ Animated Checker Wrap uses the exact original 2048px alpha mask and two inverse black/white checker frames, swapping every 0.25 seconds. VIP-only; appears automatically under GHILLIE WRAP on compatible guns. No UAV repack required. VIP menu: PREFIX, KILLFEED and GUN RESKINS tabs in the black and white loadout style. Reskin categories 20mm, .50 cal, .408 and Other, with ghillie selector under the preview. Uses existing profiles/GRZ_Killfeed/config.json AllowedSteamIds; compatible suppressors are automatic for VIP loadout grants. Additional paid classes can be configured in profiles/GRZ_Loadout/vip-reskins.json. Future animated wraps should set GRZVipOnly=1. Movement: reduced strafe and turn delays while preserving existing acceleration/camera features and stamina. Native gait top speeds remain unchanged. Map rotation notifications now use explicit alpha-textured black backgrounds. Clothing Save and Apply now uses authoritative networked inventory moves, so worn clothes and transferred contents update without respawning. Saved character appearance is still used at respawn. AR50 audio: uploaded UAV_Ak50 shot with dedicated close/mid/far layers, installed through GRZ_AR50Sounds.pbo on both sides. No UAV repack required. Siphon: killing another player or survivor bot fully restores the living killer health, blood, shock and body damage, and clears bleeding. No reward for suicide. Gear is unchanged. Includes GRZ_SFGPermanent.pbo on BOTH sides: SFG uses a native weaponMuzzleM4 proxy and matching hidden, locked suppressor attachment for held-weapon rendering. Suppressed firing sounds remain built into its firing mode. VPP/loadout SFGs get a hunting optic, and the loadout preview uses the integrated model. Requires the original sfg50 weapon addon. Admin !skip warns players at the top, then switches to the next arena after 30 seconds. Duel players remain in their match. Loadout adds BAG, locks gameplay inputs in menus, and supports left-click dragging the clothing character through 360 degrees. The viewing angle stays when changing clothes. Death screen waits 2 seconds, fades over 0.8 seconds, and hides gameplay HUD. Right-side RESPAWN opens SPAWN CUSTOM (saved character) or SPAWN RANDOM (random character). Both restore the same saved clothes and weapon and use the existing active-arena spawn system.\nStatic/package checks only; DayZ runtime untested.\n')
(r/'downloads/GRZ-SFG-Native-Muzzle-Update.zip').write_bytes((r/'downloads/GRZ-Arena-Menu-Update.zip').read_bytes())
print('Built GRZ-Arena-Menu-Update.zip and GRZ-SFG-Native-Muzzle-Update.zip')
